-- ICSS Plaza uses a server-only schema. Storefront clients use the Node API.
CREATE SCHEMA IF NOT EXISTS icss_plaza;
REVOKE ALL ON SCHEMA icss_plaza FROM PUBLIC, anon, authenticated, service_role;
CREATE TABLE IF NOT EXISTS icss_plaza.users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,created BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.tenants(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,owner TEXT NOT NULL REFERENCES icss_plaza.users(id),status TEXT NOT NULL DEFAULT 'trial',trial_end BIGINT NOT NULL,settings TEXT NOT NULL,created BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES icss_plaza.users(id),csrf TEXT NOT NULL,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.products(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES icss_plaza.tenants(id),data TEXT NOT NULL,created BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS products_tenant ON icss_plaza.products(tenant_id);
 CREATE TABLE IF NOT EXISTS icss_plaza.gateways(tenant_id TEXT NOT NULL REFERENCES icss_plaza.tenants(id),provider TEXT NOT NULL,enabled INTEGER NOT NULL,config TEXT NOT NULL,PRIMARY KEY(tenant_id,provider));
 CREATE TABLE IF NOT EXISTS icss_plaza.orders(id TEXT PRIMARY KEY,short_id TEXT NOT NULL UNIQUE,tenant_id TEXT NOT NULL REFERENCES icss_plaza.tenants(id),token_hash TEXT NOT NULL,idempotency TEXT NOT NULL,request_hash TEXT NOT NULL,data TEXT NOT NULL,state TEXT NOT NULL,paid INTEGER NOT NULL DEFAULT 0,transaction_id TEXT,created BIGINT NOT NULL,UNIQUE(tenant_id,idempotency));
 CREATE UNIQUE INDEX IF NOT EXISTS payment_transaction ON icss_plaza.orders(tenant_id,transaction_id) WHERE transaction_id IS NOT NULL;
 CREATE INDEX IF NOT EXISTS orders_tenant ON icss_plaza.orders(tenant_id);
 CREATE TABLE IF NOT EXISTS icss_plaza.images(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES icss_plaza.tenants(id),mime TEXT NOT NULL,name TEXT NOT NULL,bytes BYTEA NOT NULL,created BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.audit(id TEXT PRIMARY KEY,tenant_id TEXT,actor TEXT NOT NULL,action TEXT NOT NULL,created BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.requests(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES icss_plaza.tenants(id),kind TEXT NOT NULL,note TEXT NOT NULL,created BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.resets(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES icss_plaza.users(id),expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS icss_plaza.metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE INDEX IF NOT EXISTS tenants_owner ON icss_plaza.tenants(owner);
 CREATE INDEX IF NOT EXISTS sessions_user ON icss_plaza.sessions(user_id);
 CREATE INDEX IF NOT EXISTS sessions_expires ON icss_plaza.sessions(expires);
 CREATE INDEX IF NOT EXISTS resets_user ON icss_plaza.resets(user_id);
 CREATE INDEX IF NOT EXISTS resets_expires ON icss_plaza.resets(expires);
 CREATE INDEX IF NOT EXISTS images_tenant ON icss_plaza.images(tenant_id);
 CREATE INDEX IF NOT EXISTS requests_tenant ON icss_plaza.requests(tenant_id);
 REVOKE ALL ON ALL TABLES IN SCHEMA icss_plaza FROM PUBLIC, anon, authenticated, service_role;
 ALTER TABLE icss_plaza.users ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.tenants ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.sessions ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.products ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.gateways ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.orders ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.images ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.audit ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.requests ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.resets ENABLE ROW LEVEL SECURITY;
 ALTER TABLE icss_plaza.metadata ENABLE ROW LEVEL SECURITY;
